It 'rooted drive path is unsafe'{$r=Fixture @(Row 'C:/README.md');try{Check $r 1 'rooted drive' 'not a safe repository-root-relative path'}finally{Remove-Item -Recurse -Force $r}}
It 'drive-relative path is classified unsafe before path shape'{$r=Fixture @(Row 'C:README.md');try{Check $r 1 'drive-relative path' 'not a safe repository-root-relative path'}finally{Remove-Item -Recurse -Force $r}}
It 'duplicate exact hazard headings are rejected'{$r=Fixture -Missing;try{WriteRawContext $r @('# Context',$hazardHeading,$hazardHeader,$hazardSeparator,(Row 'src/Payments.cs'),'## Other','text',$hazardHeading,$hazardHeader,$hazardSeparator,(Row 'src/Payments.cs'),'## Next');Make $r 'src/Payments.cs';Check $r 1 'duplicate headings' 'exactly one'}finally{Remove-Item -Recurse -Force $r}}
