It 'exact heading accepts trailing horizontal whitespace'{$r=Fixture -Missing;try{WriteRawContext $r @('# Context',($hazardHeading+"`t  "),$hazardHeader,$hazardSeparator,(Row 'src/Payments.cs'),'## Next');Make $r 'src/Payments.cs';Check $r 0 'heading horizontal whitespace'}finally{Remove-Item -Recurse -Force $r}}
It 'exact no-notable outcome passes beside a case-variant pending decoy'{$r=Fixture -Missing;try{WriteRawContext $r @('# Context','Known_Hazard_Areas_Pending',$hazardHeading,$hazardHeader,$hazardSeparator,$noNotable,'## Next');Check $r 0 'no-notable outcome' 'hazard-check passed.'}finally{Remove-Item -Recurse -Force $r}}
