It 'docs-sync rejects the bracket glob bypass without final success'{$r=ConsumerFixture @(Row 'src/file[0].cs');try{Make $r 'src/file[0].cs';CheckDocs $r 1 'docs bracket bypass' 'hazard map checks failed'}finally{Remove-Item -Recurse -Force $r}}
It 'framed exact dot segments remain unsafe without becoming missing paths'{$area='`.` `src/.` `src/..` `src/..:` `src/...` `(src/..);` `''(src/..);''` `(src/..).` `(src/..):` `''(src/..);''.` `''(src/..);'':` `"(src/..),;;"` `README.md`';$r=ConsumerFixture @(Row $area);try{$controls=@('src','src/..)','src/..)''','src/..);''','(src/..)','''(src/..);''');foreach($control in $controls){$null=[IO.Directory]::CreateDirectory((Join-Path $r $control))};Make $r 'README.md';$leaf=CaptureLeaf $r;$docs=CaptureDocs $r;foreach($control in $controls){Assert([IO.Directory]::Exists((Join-Path $r $control)))"dot segment control was not created: $control"};$unsafe='hazard row names a path that is not a safe repository-root-relative path:';AssertLeaf $leaf 1 'dot segment safety' '12 hazard-check failure(s).';AssertDocs $docs 1 'docs dot segment safety' 'hazard map checks failed';foreach($capture in @(@{n='leaf ps1';o=$leaf.P.Out},@{n='docs ps1';o=$docs.P.Out})){Assert((CountText $capture.o $unsafe)-eq12)"$($capture.n) did not report exactly 12 unsafe paths: $($capture.o)";Assert($capture.o-notmatch'does not exist')"$($capture.n) misclassified an unsafe path as missing: $($capture.o)"};Assert($leaf.P.Out-notmatch'(?m)^hazard-check passed\.\r?$')'dot segment ps1 leaf printed false success'}finally{Remove-Item -Recurse -Force $r}}
It 'bare drive prefix remains unsafe beside a valid literal'{$r=Fixture @(Row '`C:` `README.md`');try{Make $r 'README.md';Check $r 1 'bare drive prefix' 'not a safe repository-root-relative path'}finally{Remove-Item -Recurse -Force $r}}
It 'header and separator alone are not a completed outcome'{$r=Fixture @();try{Check $r 1 'header-only section' 'at least one hazard row or the exact no-notable outcome'}finally{Remove-Item -Recurse -Force $r}}
It 'arbitrary non-table prose is not a completed outcome'{$r=Fixture -Missing;try{WriteRawContext $r @('# Context',$hazardHeading,'_Something else._','## Next');Check $r 1 'arbitrary outcome' 'at least one hazard row or the exact no-notable outcome'}finally{Remove-Item -Recurse -Force $r}}
It 'no-notable outcome cannot be mixed with a real row'{$r=Fixture @($noNotable,(Row 'README.md'));try{Make $r 'README.md';Check $r 1 'mixed outcome' 'cannot contain both'}finally{Remove-Item -Recurse -Force $r}}
It 'framed dot-named and unmatched-wrapper paths remain literal'{$spellings=@('`(src/.cache/config.json);`','`''(src/.cache/config.json);''`','`(src/.cache/config.json).`','`(src/.cache/config.json):`','`''(src/.cache/config.json);''.`','`''(src/.cache/config.json);'':`','`"(src/.cache/config.json),;;"`','`src/.cache/(unmatched-leading.json`','`src/.cache/unmatched.json)`','`src/.cache/unmatched-single.json''`');$rows=@();foreach($spelling in $spellings){$rows+=Row $spelling};$r=ConsumerFixture $rows;try{$cache=[IO.Directory]::CreateDirectory((Join-Path $r 'src/.cache')).FullName;foreach($name in @('config.json','(unmatched-leading.json','unmatched.json)','unmatched-single.json''')){Put(Join-Path $cache $name)'x'};$leaf=CaptureLeaf $r;$docs=CaptureDocs $r;foreach($absent in @('unmatched-leading.json','unmatched.json','unmatched-single.json')){Assert(-not[IO.File]::Exists((Join-Path $cache $absent)))"unmatched-wrapper stripped control unexpectedly exists: $absent"};AssertLeaf $leaf 0 'framed dot-named paths' 'hazard-check passed.';AssertDocs $docs 0 'docs framed dot-named paths' 'hazard-check passed.'}finally{Remove-Item -Recurse -Force $r}}
It 'ordinary path accepts one sentence-final dot and colon'{$r=Fixture @(Row '`src/Payments.cs.` `src/Payments.cs:`');try{Make $r 'src/Payments.cs';Check $r 0 'sentence punctuation'}finally{Remove-Item -Recurse -Force $r}}
It 'case-variant no-notable text is not the exact outcome'{$r=Fixture @('_No Notable hazards detected — confirm with the team._');try{Check $r 1 'case-variant no-notable' 'at least one hazard row or the exact no-notable outcome'}finally{Remove-Item -Recurse -Force $r}}
It 'no-notable text with trailing garbage is not the exact outcome'{$r=Fixture @("$noNotable trailing");try{Check $r 1 'garbage no-notable' 'at least one hazard row or the exact no-notable outcome'}finally{Remove-Item -Recurse -Force $r}}
It 'docs-sync captures every incomplete lifecycle state before asserting'{$r=ConsumerFixture @(Row 'README.md');try{$captures=[Collections.Generic.List[object]]::new();$context=Join-Path $r 'FRAMEWORK-CONTEXT.md';Remove-Item -LiteralPath $context -Force;$captures.Add([pscustomobject]@{Label='docs missing context';Expected=1;Text='FRAMEWORK-CONTEXT.md is missing';Pair=(CaptureDocs $r)});WriteContext $r @() -Pending;$captures.Add([pscustomobject]@{Label='docs pending';Expected=1;Text='still pending';Pair=(CaptureDocs $r)});WriteContext $r @() -NoSection;$captures.Add([pscustomobject]@{Label='docs absent section';Expected=1;Text='exactly one';Pair=(CaptureDocs $r)});WriteContext $r @('| _(drafted by /bootstrap)_ | _ | _ | _ |');$captures.Add([pscustomobject]@{Label='docs placeholder';Expected=1;Text='placeholder row';Pair=(CaptureDocs $r)});WriteContext $r @();$captures.Add([pscustomobject]@{Label='docs header only';Expected=1;Text='at least one hazard row or the exact no-notable outcome';Pair=(CaptureDocs $r)});WriteRawContext $r @('# Context',$hazardHeading,'_Something else._','## Next');$captures.Add([pscustomobject]@{Label='docs arbitrary prose';Expected=1;Text='at least one hazard row or the exact no-notable outcome';Pair=(CaptureDocs $r)});WriteContext $r @($noNotable,(Row 'README.md'));$captures.Add([pscustomobject]@{Label='docs mixed outcome';Expected=1;Text='cannot contain both';Pair=(CaptureDocs $r)});WriteContext $r @($noNotable);$captures.Add([pscustomobject]@{Label='docs no-notable';Expected=0;Text='hazard-check passed.';Pair=(CaptureDocs $r)});foreach($capture in $captures){AssertDocs $capture.Pair $capture.Expected $capture.Label $capture.Text}}finally{Remove-Item -Recurse -Force $r}}
Write-Output "[coverage] HazardCheck subjects: ps1 leaf=$script:leafPsRuns wrapper=$script:wrapperPsRuns"
$coverageOK=$script:leafPsRuns-eq63-and$script:wrapperPsRuns-eq14
$summaryExit=Write-TestSummary 'HazardCheck.Tests';if(-not$coverageOK){Write-Output '[FAIL] HazardCheck subject count drifted; expected 63 leaf + 14 wrapper runs.';exit 1};exit $summaryExit
